Hunt for bugs in this function, our invoice totals look off:

function invoiceTotal(lines, taxRate) {
  // sum of quantity * unitPrice for every line, then add tax (taxRate is a percent, e.g. 7 for 7%)
  let total = 0;
  for (const line of lines) total += line.quantity * line.unitPrice;
  return total + total * taxRate;
}
